cd /workspace/graphic && python3 - <<'EOF'
p='js/template.js'
s=open(p).read()
old="if (STAGE_FIT_BOXES.indexOf('.quiz-box') < 0) STAGE_FIT_BOXES.push('.quiz-box');"
assert old in s
s=s.replace(old,"// This board fits its own text (fitQuizText, below update()), so .quiz-box is not registered\n// with the stage fit: the question and answers shrink to their tiles instead of being held to the\n// sample's row count.")
old="""  if (typeof fitStagedText === 'function') fitStagedText();
}"""
new="""  fitQuizText();
}

// fitQuizText(): long questions and answers are normal on this show. Each text keeps its
// design size while it fits its room, and steps down (never under QUIZ_FIT_FLOOR) when it does
// not: the question gets three rows at its design size, an answer the inside of its tile.
var QUIZ_FIT_FLOOR = 22;
function quizFitOne(el, maxH) {
  el.style.fontSize = '';
  var design = parseFloat(window.getComputedStyle(el).fontSize);
  if (!design || !maxH) return;
  var floor = Math.max(QUIZ_FIT_FLOOR, Math.round(design * 0.6));
  var size = design;
  while (el.offsetHeight > maxH + 1 && size > floor) {
    size = Math.max(floor, size - 1);
    el.style.fontSize = size + 'px';
  }
}
function fitQuizText() {
  var q = document.getElementById('f0');
  if (q) {
    q.style.fontSize = '';
    var qs = parseFloat(window.getComputedStyle(q).fontSize) || 0;
    quizFitOne(q, Math.ceil(qs * 1.18 * 3));
  }
  var texts = document.querySelectorAll('.quiz-text');
  for (var i = 0; i < texts.length; i++) {
    var tile = texts[i].parentNode;
    var cs = window.getComputedStyle(tile);
    var room = parseFloat(cs.minHeight) - (parseFloat(cs.paddingTop) || 0) - (parseFloat(cs.paddingBottom) || 0);
    quizFitOne(texts[i], room);
  }
}
if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', fitQuizText);
else fitQuizText();
if (document.fonts && document.fonts.ready && document.fonts.ready.then) document.fonts.ready.then(fitQuizText);"""
